// ------------------------------------------------------------------ formatting
const LOCALE: Record<Lang, string> = { en: "en-GB", ne: "ne-u-nu-latn", hi: "hi-u-nu-latn", bn: "bn-u-nu-latn", sw: "sw", fr: "fr", es: "es", pt: "pt" };

interface F { d: (day: Day) => string; months: (ms: number[]) => string; sign: (x: number) => string; ord: (x: number) => string }
function formatters(lang: Lang): F {
  const loc = LOCALE[lang];
  const df = new Intl.DateTimeFormat(loc, { day: "numeric", month: "short", timeZone: "UTC" });
  const mf = new Intl.DateTimeFormat(loc, { month: "long", timeZone: "UTC" });
  const lf = new Intl.ListFormat(loc, { type: "conjunction" });
  return {
    d: (day) => df.format(new Date(day * 86_400_000)),
    months: (ms) => lf.format(ms.map((m) => mf.format(new Date(Date.UTC(2001, m - 1, 15))))),
    sign: (x) => `${x > 0 ? "+" : x < 0 ? "−" : ""}${Math.abs(x)}`,
    ord: (x) => {
      const s = x % 100 >= 11 && x % 100 <= 13 ? "th" : ({ 1: "st", 2: "nd", 3: "rd" } as Record<number, string>)[x % 10] ?? "th";
      return `${x}${s}`;
    },
  };
}

// ------------------------------------------------------------------ messages
type V = AdviceVars & Record<string, any>;
type Msg = (v: V, f: F) => { t: string; a: string; w: string };
type Phrases = {
  phase: (p: string) => string;
  status: Record<string, string>;
  now: (v: V) => string;
  hist: (v: V, f: F, above: boolean) => string;
  m: Record<AdviceId, Msg>;
};

const EN: Phrases = {
  phase: (p) => (p === "El Nino" ? "El Niño" : "La Niña"),
  status: { active: "is under way", developing: "is developing", expected: "is forecast" },
  now: (v) => `${EN.phase(v.phase)} ${EN.status[v.status]}`,
  hist: (v, f, above) => `In ${v.k} of ${v.n} past ${EN.phase(v.phase)} seasons here, rain for this crop season was ${above ? "above" : "below"} the 1991–2020 normal (median ${f.sign(v.median)}%)${v.clear ? "." : "; the difference from neutral seasons is not statistically clear."}`,
  m: {
    rain_low: (v, f) => ({ t: "Rain since sowing is well below normal",
      w: `Season rainfall so far is at the ${f.ord(v.pct)} percentile of 1991–2020, and the crop has needed about ${v.gap} mm more water than effective rain supplied.`,
      a: v.mid0 != null ? `If water for irrigation is limited, save it for the mid-season stage (${f.d(v.mid0)} – ${f.d(v.mid1)}), when water shortage reduces yield the most.` : "If water for irrigation is limited, save it for flowering and grain or yield formation, when water shortage reduces yield the most." }),
    soil_dry: (v, f) => ({ t: "Soil is unusually dry for the time of year",
      w: `ERA5 root-zone soil moisture (0–100 cm) is at the ${f.ord(v.pct)} percentile for this time of year (1991–2020).`,
      a: "Reduce evaporation from the soil surface, for example by keeping crop residue or mulch on the field." }),
    heat_mid: (v) => ({ t: "Heat forecast during the mid-season stage",
      w: `On ${v.hot} of the next ${v.n} days the ensemble median maximum temperature is above ${v.thr} °C, while the crop is in its mid-season stage.`,
      a: "Temperatures above this level during flowering are linked to yield loss. Where irrigation is available, avoid letting the crop run short of water during these days." }),
    heavy_rain: (v, f) => ({ t: "Heavy rain possible",
      w: `The ensemble median gives about ${v.mm} mm over three days starting ${f.d(v.start)}.`,
      a: "Clear field drains and avoid applying fertiliser or pesticide just before the rain, so it is not washed off." }),
    seas_dry: (v, f) => ({ t: v.inSeason ? "Seasonal forecast leans dry for the sensitive stage" : "Seasonal forecast leans dry for the coming season",
      w: `ECMWF SEAS5 ensemble-mean rainfall for ${f.months(v.months)} is at least 20% below the model's own normal.`,
      a: v.inSeason ? "Plan now for supplementary irrigation or water harvesting around flowering, and keep soil cover to hold moisture." : "If you have not sown yet, discuss shorter-duration or drought-tolerant varieties with your extension office." }),
    seas_wet: (v, f) => ({ t: "Seasonal forecast leans wet",
      w: `ECMWF SEAS5 ensemble-mean rainfall for ${f.months(v.months)} is at least 20% above the model's own normal.`,
      a: "Check that field drains and bunds are in order, and plan fertiliser applications in splits so less is washed out." }),
    dry_fortnight: (v) => ({ t: "The next two weeks look dry",
      w: `The ECMWF ensemble median gives ${v.total} mm over the next 15 days. The same dates in 1991–2020 had a median of ${v.normal} mm (ERA5), so this is drier than ${v.drierThan}% of those years.`,
      a: v.inSeason ? "Check soil moisture and plan irrigation for the next two weeks, giving priority to fields that are flowering." : "Wait for enough rain to wet the soil before sowing; seed sown into dry soil may fail to establish." }),
    enso_pending: (v) => ({ t: EN.now(v),
      w: "NOAA CPC Relative Oceanic Niño Index and the ECMWF SEAS5 Niño-3.4 forecast.",
      a: v.loading ? `Checking how past ${EN.phase(v.phase)} seasons went here…` : `See how past ${EN.phase(v.phase)} seasons went here, in the ${EN.phase(v.phase)} impact section above.` }),
    enso_dry_pre: (v, f) => ({ t: "Prepare for a drier season than normal", w: `${EN.now(v)}. ${EN.hist(v, f, false)}`,
      a: "If a shorter-duration or drought-tolerant variety suited to your area is available, consider it. Sow once the soil is moist enough, and have water harvesting and soil cover (crop residue or mulch) ready before the season." }),
    enso_dry_in: (v, f) => ({ t: "Expect the rest of the season to stay drier than normal",
      w: `${EN.now(v)}. ${EN.hist(v, f, false)}${v.soFar != null ? ` Rain so far this season is at the ${f.ord(v.soFar)} percentile of 1991–2020.` : ""}`,
      a: `Keep crop residue or mulch on the soil and keep weeds down so they do not take water.${v.mid0 != null ? ` Save irrigation water for the mid-season stage (${f.d(v.mid0)} – ${f.d(v.mid1)}).` : v.hasPlan ? "" : " Save irrigation water for flowering."}` }),
    enso_wet: (v, f) => ({ t: "Prepare for a wetter season than normal", w: `${EN.now(v)}. ${EN.hist(v, f, true)}`,
      a: "Clear field drains, check for fungal disease after long wet spells, and split fertiliser applications so less is washed out." }),
    enso_none: (v, f) => ({ t: `${EN.phase(v.phase)} has had no consistent effect on rain here`,
      w: `${EN.now(v)}. Of ${v.n} past ${EN.phase(v.phase)} seasons here, ${v.drier} were drier and ${v.wetter} wetter than normal (median ${f.sign(v.median)}%).`,
      a: "Plan for the normal range of rainfall and follow the 15-day and monthly forecasts." }),
    enso_hot: (v) => ({ t: `${EN.phase(v.phase)} seasons have been hotter here`,
      w: `Past ${EN.phase(v.phase)} seasons were a median ${v.tAnom} °C warmer than the long-term trend (daily maximum), a consistent difference from neutral seasons.`,
      a: `Heat above ${v.thr} °C at flowering reduces yield. Do not let the crop run short of water around flowering.` }),
  },
};

